// Validate and normalize the lecture supplied by QA Master.
const src = items[0]?.json || {};

const meetingId = String(src.meetingId || '').trim();
const module = String(src.module || '').trim();
const subject = String(src.subject || module).trim();
const scheduledStart = String(src.scheduledStart || '').trim();
const scheduledEnd = String(src.scheduledEnd || '').trim();
const targetDate = String(src.targetDate || scheduledStart.slice(0, 10)).trim();

const missing = [];
if (!meetingId) missing.push('meetingId');
if (!module) missing.push('module');
if (!targetDate) missing.push('targetDate');
if (!scheduledStart) missing.push('scheduledStart');
if (!scheduledEnd) missing.push('scheduledEnd');
if (missing.length) {
  throw new Error('QA One Lecture missing required input(s): ' + missing.join(', '));
}

return [{
  json: {
    meetingId,
    module,
    subject,
    targetDate,
    scheduledStart,
    scheduledEnd
  }
}];

// Combine multiple Microsoft VTT transcript parts
// while preserving their correct chronological offsets.
//
// Run Once for All Items.

if (!items || items.length === 0) {
  return [];
}

const selectedMetadata =
  $items("Select Transcript Parts") || [];

function getText(item) {
  return String(
    item?.json?.data ??
    item?.json?.body ??
    item?.json?.transcriptText ??
    item?.json?.text ??
    ''
  );
}

function getPairedIndex(item, fallbackIndex) {
  const paired = item?.pairedItem;

  if (Array.isArray(paired)) {
    const firstIndex = paired[0]?.item;

    return Number.isInteger(firstIndex)
      ? firstIndex
      : fallbackIndex;
  }

  if (
    paired &&
    Number.isInteger(paired.item)
  ) {
    return paired.item;
  }

  return fallbackIndex;
}

function stripWebvttHeader(value) {
  return String(value || '')
    .replace(
      /^\uFEFF?\s*WEBVTT[^\r\n]*(?:\r?\n)+/i,
      ''
    )
    .trim();
}

function timestampToMs(
  hours,
  minutes,
  seconds,
  milliseconds
) {
  return (
    (
      (
        Number(hours) * 60 +
        Number(minutes)
      ) * 60 +
      Number(seconds)
    ) * 1000 +
    Number(milliseconds)
  );
}

function formatTimestamp(totalMs) {
  const safeMs =
    Math.max(0, Math.round(totalMs));

  const hours =
    Math.floor(safeMs / 3600000);

  const minutes =
    Math.floor(
      (safeMs % 3600000) / 60000
    );

  const seconds =
    Math.floor(
      (safeMs % 60000) / 1000
    );

  const milliseconds =
    safeMs % 1000;

  return (
    String(hours).padStart(2, '0') +
    ':' +
    String(minutes).padStart(2, '0') +
    ':' +
    String(seconds).padStart(2, '0') +
    '.' +
    String(milliseconds).padStart(3, '0')
  );
}

function shiftVttTimestamps(vtt, offsetMs) {
  const body =
    stripWebvttHeader(vtt);

  const timingRegex =
    /(\d{2,}):(\d{2}):(\d{2})[.,](\d{3})(\s*-->\s*)(\d{2,}):(\d{2}):(\d{2})[.,](\d{3})/g;

  return body.replace(
    timingRegex,
    (
      match,
      startHour,
      startMinute,
      startSecond,
      startMillisecond,
      arrow,
      endHour,
      endMinute,
      endSecond,
      endMillisecond
    ) => {
      const originalStartMs =
        timestampToMs(
          startHour,
          startMinute,
          startSecond,
          startMillisecond
        );

      const originalEndMs =
        timestampToMs(
          endHour,
          endMinute,
          endSecond,
          endMillisecond
        );

      return (
        formatTimestamp(
          originalStartMs + offsetMs
        ) +
        arrow +
        formatTimestamp(
          originalEndMs + offsetMs
        )
      );
    }
  );
}

function scanVttRangeMs(vtt) {
  const timingRegex =
    /(\d{2,}):(\d{2}):(\d{2})[.,](\d{3})\s*-->\s*(\d{2,}):(\d{2}):(\d{2})[.,](\d{3})/g;

  let minimumMs =
    Number.POSITIVE_INFINITY;

  let maximumMs = 0;
  let match;

  while ((match = timingRegex.exec(vtt))) {
    const startMs =
      timestampToMs(
        match[1],
        match[2],
        match[3],
        match[4]
      );

    const endMs =
      timestampToMs(
        match[5],
        match[6],
        match[7],
        match[8]
      );

    minimumMs =
      Math.min(minimumMs, startMs);

    maximumMs =
      Math.max(maximumMs, endMs);
  }

  if (
    minimumMs === Number.POSITIVE_INFINITY
  ) {
    return {
      min: null,
      max: null
    };
  }

  return {
    min: minimumMs,
    max: maximumMs
  };
}


// ---------------------------------------------------------
// Match downloaded VTT items to Select Transcript Parts
// ---------------------------------------------------------

const parts = items.map((item, itemIndex) => {
  const sourceIndex =
    getPairedIndex(item, itemIndex);

  const metadata =
    selectedMetadata[sourceIndex]?.json ||
    selectedMetadata[itemIndex]?.json ||
    {};

  const text =
    getText(item);

  const partCreatedDateTime =
    metadata.partCreatedDateTime ||
    metadata.createdDateTime ||
    null;

  const partCreatedMs =
    Date.parse(partCreatedDateTime);

  return {
    text,
    metadata,
    partCreatedMs:
      Number.isFinite(partCreatedMs)
        ? partCreatedMs
        : null
  };
});

const validParts = parts.filter(part => {
  return (
    part.text.trim().length > 0 &&
    Number.isFinite(part.partCreatedMs)
  );
});

if (!validParts.length) {
  throw new Error(
    'No valid transcript parts were downloaded'
  );
}


// ---------------------------------------------------------
// Sort by the real Microsoft transcript start time
// ---------------------------------------------------------

validParts.sort((a, b) => {
  return a.partCreatedMs - b.partCreatedMs;
});

const sessionStartMs = Math.min(
  ...validParts.map(part => part.partCreatedMs)
);


// ---------------------------------------------------------
// Shift each VTT part onto one continuous session timeline
// ---------------------------------------------------------

const combinedSections =
  validParts.map(part => {
    const offsetMs =
      part.partCreatedMs - sessionStartMs;

    return shiftVttTimestamps(
      part.text,
      offsetMs
    );
  });

const combinedBody =
  combinedSections
    .filter(Boolean)
    .join('\n\n');

const transcriptText =
  `WEBVTT\n\n${combinedBody}`.trim();

const range =
  scanVttRangeMs(transcriptText);

const durationMinutes =
  range.min !== null &&
  range.max !== null &&
  range.max >= range.min
    ? Math.round(
        (range.max - range.min) / 60000
      )
    : null;

if (
  typeof durationMinutes !== 'number' ||
  durationMinutes <= 0
) {
  throw new Error(
    `Invalid combined transcript duration: ${durationMinutes}`
  );
}

return [
  {
    json: {
      durationMinutes,
      transcriptText,

      transcriptPartsSelected:
        selectedMetadata.length,

      transcriptPartsCombined:
        validParts.length,

      transcriptPartsFailed:
        Math.max(
          0,
          selectedMetadata.length -
          validParts.length
        ),

      transcriptCombined:
        validParts.length > 1
    }
  }
];

// Select Transcript Parts V3
// n8n Code node - Run Once for All Items
//
// IMPORTANT:
// In THIS workflow, scheduledStart / scheduledEnd coming from QA Master
// are already UTC timestamps even when they do NOT end with Z.
//
// Example:
// 2026-08-07T08:00:00.0000000
// means 08:00 UTC, NOT 08:00 Cairo.
//
// Microsoft Graph transcript timestamps already come as UTC with Z.

const TZ = 'Africa/Cairo';

const lecture = $items("Lecture Input")[0]?.json || {};

const targetDate = String(lecture.targetDate || '').trim();
const scheduledStartRaw = String(lecture.scheduledStart || '').trim();
const scheduledEndRaw = String(lecture.scheduledEnd || '').trim();
const meetingId = String(lecture.meetingId || '').trim();

const transcripts = items[0]?.json?.value ?? [];

if (!Array.isArray(transcripts) || transcripts.length === 0) {
  return [];
}


// ---------------------------------------------------------
// Parse scheduled timestamps as UTC
// ---------------------------------------------------------

function scheduledToUtcMs(value) {
  if (!value) return null;

  const s = String(value).trim();

  // Already timezone-aware
  if (
    /Z$/i.test(s) ||
    /[+-]\d{2}:\d{2}$/.test(s)
  ) {
    const ms = Date.parse(s);
    return Number.isFinite(ms) ? ms : null;
  }

  // QA Master sends UTC without trailing Z.
  //
  // Also trim excessive fractional seconds because JS Date.parse
  // is safest with milliseconds.
  //
  // Example:
  // 2026-08-07T08:00:00.0000000
  // ->
  // 2026-08-07T08:00:00.000Z

  let cleaned = s;

  cleaned = cleaned.replace(
    /\.(\d{3})\d+/,
    '.$1'
  );

  const ms = Date.parse(cleaned + 'Z');

  return Number.isFinite(ms) ? ms : null;
}


const scheduledStartMs =
  scheduledToUtcMs(scheduledStartRaw);

const scheduledEndMs =
  scheduledToUtcMs(scheduledEndRaw);

if (
  !Number.isFinite(scheduledStartMs) ||
  !Number.isFinite(scheduledEndMs)
) {
  throw new Error(
    `Invalid scheduled times. start=${scheduledStartRaw}, end=${scheduledEndRaw}`
  );
}

if (scheduledEndMs <= scheduledStartMs) {
  throw new Error(
    `scheduledEnd must be after scheduledStart. start=${scheduledStartRaw}, end=${scheduledEndRaw}`
  );
}

const scheduledStartUtc =
  new Date(scheduledStartMs).toISOString();

const scheduledEndUtc =
  new Date(scheduledEndMs).toISOString();


// ---------------------------------------------------------
// Helper: get Cairo calendar date for Graph timestamp
// ---------------------------------------------------------

function getCairoDate(iso) {
  const ms = Date.parse(iso);

  if (!Number.isFinite(ms)) {
    return null;
  }

  return new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date(ms));
}


// ---------------------------------------------------------
// Step 1: Same meeting + same target Cairo date
// ---------------------------------------------------------

const sameDay = transcripts.filter(t => {
  if (!t?.createdDateTime) {
    return false;
  }

  // Safety check
  if (
    meetingId &&
    t.meetingId &&
    t.meetingId !== meetingId
  ) {
    return false;
  }

  const cairoDate =
    getCairoDate(t.createdDateTime);

  return cairoDate === targetDate;
});

if (!sameDay.length) {
  return [];
}


// ---------------------------------------------------------
// Step 2: Keep only transcripts near this occurrence
//
// Window:
// 2 hours before scheduled start
// 3 hours after scheduled end
//
// This avoids accidentally selecting another session.
// ---------------------------------------------------------

const WINDOW_BEFORE_MS =
  2 * 60 * 60 * 1000;

const WINDOW_AFTER_MS =
  3 * 60 * 60 * 1000;

const candidates = sameDay.filter(t => {
  const startMs =
    Date.parse(t.createdDateTime);

  const endMs =
    Date.parse(
      t.endDateTime ||
      t.createdDateTime
    );

  if (
    !Number.isFinite(startMs) ||
    !Number.isFinite(endMs)
  ) {
    return false;
  }

  return (
    endMs >=
      scheduledStartMs - WINDOW_BEFORE_MS
    &&
    startMs <=
      scheduledEndMs + WINDOW_AFTER_MS
  );
});

if (!candidates.length) {
  return [];
}


// ---------------------------------------------------------
// Sort chronologically
// ---------------------------------------------------------

candidates.sort((a, b) => {
  return (
    Date.parse(a.createdDateTime) -
    Date.parse(b.createdDateTime)
  );
});


// ---------------------------------------------------------
// ---------------------------------------------------------
// Step 3: Choose the main transcript intelligently
//
// Primary transcript:
// - largest overlap with scheduled lecture
// - then longest duration
// - then closest start time
// ---------------------------------------------------------

const preparedCandidates = candidates.map(t => {
  const startMs = Date.parse(t.createdDateTime);

  const parsedEndMs = Date.parse(
    t.endDateTime || t.createdDateTime
  );

  const endMs =
    Number.isFinite(parsedEndMs) && parsedEndMs >= startMs
      ? parsedEndMs
      : startMs;

  const durationMs = Math.max(0, endMs - startMs);

  const overlapMs = Math.max(
    0,
    Math.min(endMs, scheduledEndMs) -
    Math.max(startMs, scheduledStartMs)
  );

  const startDistanceMs =
    Math.abs(startMs - scheduledStartMs);

  return {
    transcript: t,
    startMs,
    endMs,
    durationMs,
    overlapMs,
    startDistanceMs
  };
});

const rankedCandidates = [...preparedCandidates].sort((a, b) => {
  // Prefer the transcript covering most of the scheduled lecture
  if (b.overlapMs !== a.overlapMs) {
    return b.overlapMs - a.overlapMs;
  }

  // Then prefer the longest transcript
  if (b.durationMs !== a.durationMs) {
    return b.durationMs - a.durationMs;
  }

  // Then prefer the one closest to scheduled start
  return a.startDistanceMs - b.startDistanceMs;
});

const primaryPart = rankedCandidates[0];

if (!primaryPart) {
  return [];
}


// ---------------------------------------------------------
// Step 4: Attach nearby transcript parts
//
// Microsoft can generate a new callId when transcription
// stops and starts again.
//
// Include a part when:
// - it has the same callId as an already selected part, OR
// - it is no more than 20 minutes from the selected timeline
// ---------------------------------------------------------

const MAX_PART_GAP_MS =
  20 * 60 * 1000;

const selectedParts = [primaryPart];
const selectedIds = new Set([
  String(primaryPart.transcript.id || '')
]);

let clusterStartMs = primaryPart.startMs;
let clusterEndMs = primaryPart.endMs;

function distanceFromCluster(part) {
  if (part.endMs < clusterStartMs) {
    return clusterStartMs - part.endMs;
  }

  if (part.startMs > clusterEndMs) {
    return part.startMs - clusterEndMs;
  }

  // Overlapping
  return 0;
}

let addedNewPart = true;

while (addedNewPart) {
  addedNewPart = false;

  for (const part of preparedCandidates) {
    const partId = String(part.transcript.id || '');

    if (selectedIds.has(partId)) {
      continue;
    }

    const partCallId =
      part.transcript.callId || null;

    const hasSameCallId =
      Boolean(partCallId) &&
      selectedParts.some(selectedPart =>
        selectedPart.transcript.callId === partCallId
      );

    const gapMs =
      distanceFromCluster(part);

    const isTemporallyConnected =
      gapMs <= MAX_PART_GAP_MS;

    if (hasSameCallId || isTemporallyConnected) {
      selectedParts.push(part);
      selectedIds.add(partId);

      clusterStartMs =
        Math.min(clusterStartMs, part.startMs);

      clusterEndMs =
        Math.max(clusterEndMs, part.endMs);

      addedNewPart = true;
    }
  }
}


// ---------------------------------------------------------
// Sort selected parts chronologically
// ---------------------------------------------------------

selectedParts.sort((a, b) => {
  return a.startMs - b.startMs;
});


// ---------------------------------------------------------
// Session-level timing
// ---------------------------------------------------------

const actualStartMs = Math.min(
  ...selectedParts.map(part => part.startMs)
);

const actualEndMs = Math.max(
  ...selectedParts.map(part => part.endMs)
);

if (
  !Number.isFinite(actualStartMs) ||
  !Number.isFinite(actualEndMs)
) {
  throw new Error(
    'Selected transcripts contain invalid timing metadata'
  );
}

const actualStartUtc =
  new Date(actualStartMs).toISOString();

const actualEndUtc =
  new Date(actualEndMs).toISOString();


// ---------------------------------------------------------
// Timing differences
// ---------------------------------------------------------

const startDifferenceMinutes =
  Math.round(
    (actualStartMs - scheduledStartMs) /
    60000
  );

const endDifferenceMinutes =
  Math.round(
    (actualEndMs - scheduledEndMs) /
    60000
  );

const startStatus =
  startDifferenceMinutes === 0
    ? 'OnTime'
    : startDifferenceMinutes < 0
      ? 'Early'
      : 'Late';

const endStatus =
  endDifferenceMinutes === 0
    ? 'OnTime'
    : endDifferenceMinutes < 0
      ? 'EarlyFinish'
      : 'Overrun';


// ---------------------------------------------------------
// Primary identifiers
//
// transcriptId stays the primary transcript ID on every item.
// transcriptPartId identifies the individual downloaded part.
// ---------------------------------------------------------

const primaryTranscript =
  primaryPart.transcript;

const primaryTranscriptId =
  primaryTranscript.id || null;

const primaryCallId =
  primaryTranscript.callId || null;


// ---------------------------------------------------------
// Output
// ---------------------------------------------------------

return selectedParts.map((part, index) => {
  const t = part.transcript;

  return {
    json: {
      meetingId,

      // Stable session ID used downstream
      transcriptId:
        primaryTranscriptId,

      primaryTranscriptId,

      // ID and URL of this individual part
      transcriptPartId:
        t.id || null,

      transcriptUrl:
        t.transcriptContentUrl || null,

      // Main session call
      callId:
        primaryCallId,

      contentCorrelationId:
        primaryTranscript.contentCorrelationId || null,

      // Individual part metadata
      partCallId:
        t.callId || null,

      partContentCorrelationId:
        t.contentCorrelationId || null,

      partCreatedDateTime:
        t.createdDateTime,

      partEndDateTime:
        t.endDateTime || t.createdDateTime,

      // Full combined session timing
      createdDateTime:
        actualStartUtc,

      endDateTime:
        actualEndUtc,

      scheduledStartDateTime:
        scheduledStartRaw,

      scheduledEndDateTime:
        scheduledEndRaw,

      scheduledStartUtc,
      scheduledEndUtc,

      startDifferenceMinutes,

      startDelayAbs:
        Math.abs(startDifferenceMinutes),

      startStatus,

      endDifferenceMinutes,

      endDifferenceAbs:
        Math.abs(endDifferenceMinutes),

      endStatus,

      _isPrimary:
        t.id === primaryTranscriptId,

      _selectionMethod:
        'primary_overlap_plus_nearby_parts',

      _maximumPartGapMinutes:
        MAX_PART_GAP_MS / 60000,

      _partIndex:
        index + 1,

      _totalParts:
        selectedParts.length
    }
  };
});

// ============================================================
// Aggregate Attendees (v6 — DB-based)
//
// Source: "Attendance (DB-based)" subflow, which queries
// public.kbc_attendance filtered by module + date + Attendance=1.
//
// The DB pipeline already deduped rows and excluded bots, so this
// node mostly just shapes the output. We keep a bot filter and
// dedup as safety nets in case dirty rows slip through.
//
// Output shape (unchanged so Sessions code keeps working):
//   { meetingId, subject, date, attended_count, attendees[], _debug }
// ============================================================

const targetMeetingId = items[0]?.json?.meetingId || null;
const targetDate      = items[0]?.json?.date      || null;
const subject         = items[0]?.json?.subject   || items[0]?.json?.module || null;

// Bot / AI assistant filter (defense in depth)
function isBot(name, email) {
  const n = String(name  || '').toLowerCase();
  const e = String(email || '').toLowerCase();
  const patterns = [
    'notetaker', 'otter.ai', 'otter ai', 'read.ai', 'read ai',
    'fireflies', 'fathom', 'tldv', 'meeting bot', 'meeting notes',
    'transcript bot', 'recording bot', 'zoom ai', 'copilot',
    'teamsmaestro', 'teams maestro'
  ];
  return patterns.some(p => n.includes(p) || e.includes(p));
}

const byPerson = new Map();
let droppedByEmpty  = 0;
let droppedByNoName = 0;
let droppedByBot    = 0;

const sampleDroppedEmpty = [];

for (const it of items) {
  const j = it.json;

  // Empty placeholder from subflow = DB returned no rows for this module/date
  if (!j || j.empty) {
    droppedByEmpty++;
    if (sampleDroppedEmpty.length < 2) sampleDroppedEmpty.push(j);
    continue;
  }

  if (!j.Name || !String(j.Name).trim()) {
    droppedByNoName++;
    continue;
  }

  if (isBot(j.Name, j.Email)) {
    droppedByBot++;
    continue;
  }

  // Dedup by name+email (belt-and-suspenders; DB is already deduped)
  const key = `${String(j.Name).toLowerCase().trim()}|${String(j.Email || '').toLowerCase().trim()}`;
  if (!byPerson.has(key)) {
    byPerson.set(key, j);
  }
}

const attendees = [...byPerson.values()];

return [{
  json: {
    meetingId: targetMeetingId,
    subject,
    date: targetDate,
    attended_count: attendees.length,
    attendees,
    _debug: {
      source: 'attendance_sub_via_db',
      raw_rows_in: items.length,
      target_meeting_id: targetMeetingId,
      target_date: targetDate,
      dropped_by_empty: droppedByEmpty,
      dropped_by_no_name: droppedByNoName,
      dropped_by_bot: droppedByBot,
      final_count: attendees.length,
      sample_dropped_empty: sampleDroppedEmpty
    }
  }
}];

