=={{ 
`TRANSCRIPT:
${$json.transcriptText || ""}

METADATA:
transcriptId: ${$json.transcriptId || ""}
meetingId: ${$json.meetingId || ""}



subject: ${$items("Lecture Input")[0]?.json?.subject || ""}

scheduledStartDateTime: ${$json.scheduledStartDateTime ?? ""}
createdDateTime: ${$json.createdDateTime ?? ""}
startDifferenceMinutes : ${$json.startDifferenceMinutes ?? ""}
startStatus : ${$json.startStatus ?? ""}

scheduledEndDateTime: ${$json.scheduledEndDateTime ?? ""}
endDateTime: ${$json.endDateTime ?? ""}
