{
  "type": "object",
  "required": ["session_info", "checklist_evaluation", "overall_summary", "ksbs_covered", "teaching_quality"],
  "additionalProperties": false,
  "properties": {
    "session_info": {
      "type": "object",
      "required": ["trainer", "date"],
      "additionalProperties": false,
      "properties": {
        "trainer": { "type": "string" },
        "date": { "type": "string" }
      }
    },
    "checklist_evaluation": {
      "type": "array",
      "minItems": 11,
      "maxItems": 11,
      "items": {
        "type": "object",
