      "type": "array",
      "maxItems": 10,
      "items": {
        "type": "object",
        "required": ["type", "title", "evidence_clips"],
        "additionalProperties": false,
        "properties": {
          "type": { "type": "string", "enum": ["Knowledge", "Skill", "Behaviour"] },
          "title": { "type": "string" },
          "evidence_clips": {
            "type": "array",
            "maxItems": 3,
            "items": {
              "type": "object",
              "required": ["start", "end"],
              "additionalProperties": false,
              "properties": {
                "start": { "type": "string" },
                "end": { "type": "string" },
                "speaker": { "type": "string" }
              }
            }
          }
        }
      }
    },
    "teaching_quality": {
      "type": "object",
      "required": ["rating_1_5", "comments", "evidence_clips"],
      "additionalProperties": false,
      "properties": {
        "rating_1_5": { "type": "number", "minimum": 1, "maximum": 5 },
        "comments": { "type": "string" },
        "evidence_clips": {
          "type": "array",
          "maxItems": 3,
          "items": {
            "type": "object",
            "required": ["start", "end"],
            "additionalProperties": false,
            "properties": {
              "start": { "type": "string" },
              "end": { "type": "string" },
              "speaker": { "type": "string" }
            }
          }
        }
      }
    }
  }
}

parameters.jsCode:
// ============================================================
// Sessions code (v7 — enhanced name matching)
//
// CHANGE FROM v6:
//   isSimilar() now has a second matching method that handles
//   nicknames and shortened first names:
//
//     Method 1 (unchanged): full-string Levenshtein similarity ≥ 0.8
//                           — catches typos, minor spelling differences
//     Method 2 (NEW):        token-based subset match
//                           — every token in the shorter name matches
//                             some token in the longer name (exact,
//                             or one is a prefix of the other with
//                             both tokens ≥ 3 chars)
//
//   Handles: Chris ↔ Christopher, Nick ↔ Nicholas, Katie ↔ Katherine,
//            Sam ↔ Samuel, Alex ↔ Alexander, Rob ↔ Robert, etc.
//   Also handles: "Ali" (attendance) ↔ "Ali Mohamedin" (VTT),
//                 "Nathan" ↔ "Nathan Shields", etc.
//
//   Does NOT match: John Doe ↔ John Smith (different last names).
//
// Everything else is identical to v6.
// ============================================================

let raw = $json;
if (raw?.data) raw = raw.data;
if (raw?.output) raw = raw.output;
if (typeof raw === "string") raw = JSON.parse(raw);

const data = raw;
if (!data?.checklist_evaluation) throw new Error("AI checklist_evaluation missing");

const baseSession = $items("Merge")[0]?.json;
if (!baseSession) throw new Error("Base session missing (Merge)");

const transcriptText = baseSession.transcriptText;
if (!transcriptText) throw new Error("transcriptText missing");

const lectureRow = $items("Lecture Input")[0]?.json || {};
const subject = lectureRow.subject ?? lectureRow.Subject ?? "";

const durationMinutes = $items("Combine Transcripts")[0]?.json?.durationMinutes;
if (typeof durationMinutes !== "number" || durationMinutes <= 0) {
  throw new Error("Invalid durationMinutes");
}

const hours = Math.floor(durationMinutes / 60);
const minutes = durationMinutes % 60;
const realDurationText = minutes === 0 ? `${hours} hours` : `${hours} hours ${minutes} minutes`;

let duration_score = 1;
if (durationMinutes > 120) duration_score = 5;
else if (durationMinutes >= 115) duration_score = 4;
else if (durationMinutes >= 110) duration_score = 3;
else if (durationMinutes >= 105) duration_score = 2;

// =====================
// WebVTT parsing
// =====================
function parseTimeToMs(t) {
  const s = String(t || "").trim();
  let m = s.match(/^(\d{2}):(\d{2}):(\d{2})(?:\.(\d{1,3}))?$/);
  if (m) {
    const hh = +m[1], mm = +m[2], ss = +m[3];
    const ms = m[4] ? +String(m[4]).padEnd(3, "0") : 0;
    return (((hh * 60 + mm) * 60 + ss) * 1000) + ms;
  }
  m = s.match(/^(\d{2}):(\d{2})(?:\.(\d{1,3}))?$/);
  if (m) {
    const mm = +m[1], ss = +m[2];
    const ms = m[3] ? +String(m[3]).padEnd(3, "0") : 0;
    return (((0 * 60 + mm) * 60 + ss) * 1000) + ms;
  }
  return null;
}

function stripVttTags(s) {
  return String(s || "")
    .replace(/<\/?v[^>]*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function parseVttCues(vtt) {
  const text = String(vtt || "");
  const lines = text.split(/\r?\n/);
  const cues = [];
  const tsRe = /^(\d{2}:\d{2}:\d{2}(?:\.\d{1,3})?)\s*-->\s*(\d{2}:\d{2}:\d{2}(?:\.\d{1,3})?)/;

  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(tsRe);
    if (!m) continue;
    const startStr = m[1], endStr = m[2];
    const startMs = parseTimeToMs(startStr);
    const endMs = parseTimeToMs(endStr);
    if (startMs === null || endMs === null || endMs <= startMs) continue;

    const block = [];
    let j = i + 1;
    while (j < lines.length && lines[j].trim() !== "") { block.push(lines[j]); j++; }

    const rawBlock = block.join(" ");
    const speakerMatch = rawBlock.match(/<v[^>]*?\s([^>]+?)>/i);
    let speaker = speakerMatch ? speakerMatch[1].trim() : "";
    const cleanText = stripVttTags(rawBlock);

    if (!speaker) {
      const m2 = cleanText.match(/^([A-Za-z][A-Za-z\s.'-]{1,60}):\s/);
      if (m2) speaker = m2[1].trim();
    }

    cues.push({ startStr, endStr, startMs, endMs, speaker, text: cleanText });
    i = j;
  }

  return cues;
}

const cues = parseVttCues(transcriptText);

// =====================
// Speaker block helpers
// =====================
function normSpeaker(s) { return String(s || "").trim().toLowerCase(); }
function clipText(text, maxChars) {
  const t = String(text || "").replace(/\s+/g, " ").trim();
  if (!t) return "";
  return t.length > maxChars ? t.slice(0, maxChars).trim() + "..." : t;
}

function blocksFromRange(startStr, endStr) {
  const sMs = parseTimeToMs(startStr);
  const eMs = parseTimeToMs(endStr);
  if (sMs === null || eMs === null || eMs <= sMs) return [];

  const overlaps = cues
    .filter(c => c.startMs < eMs && c.endMs > sMs)
    .filter(c => (c.text || "").trim().length > 0)
    .sort((a, b) => a.startMs - b.startMs);

  if (!overlaps.length) return [];

  const blocks = [];
  let cur = null;
  for (const c of overlaps) {
    const sp = c.speaker || "";
    if (!cur) {
      cur = { startStr: c.startStr, endStr: c.endStr, speaker: sp, texts: [c.text], lastEndMs: c.endMs };
      continue;
    }
    const sameSpeaker = normSpeaker(cur.speaker) === normSpeaker(sp);
    const smallGap = (c.startMs - cur.lastEndMs) <= 1500;
    if (sameSpeaker && smallGap) {
      cur.endStr = c.endStr;
      cur.texts.push(c.text);
      cur.lastEndMs = c.endMs;
    } else {
      blocks.push(cur);
      cur = { startStr: c.startStr, endStr: c.endStr, speaker: sp, texts: [c.text], lastEndMs: c.endMs };
    }
  }
  if (cur) blocks.push(cur);
  return blocks;
}

// =====================
// Fuzzy matcher — v7 (Levenshtein + token-subset)
// =====================
function normalize(n) {
  return String(n || "").toLowerCase().replace(/[^a-z]/g, "");
}

function toTokens(s) {
  return String(s || "").toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map(t => t.replace(/[^a-z]/g, ""))
    .filter(t => t.length >= 2);   // ignore lone initials
}

function levenshtein(a, b) {
  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b[i - 1] === a[j - 1]) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

function isSimilar(a, b) {
  const na = normalize(a);
  const nb = normalize(b);
  if (!na || !nb) return false;

  // METHOD 1: full-string Levenshtein similarity ≥ 0.8
  // Catches typos and minor spelling variations
  //   e.g. "Zoe Dodd" ↔ "Zoë Dodd", "Katie Hewitt-Brake" ↔ "Katie Hewitt Brake"
  const dist = levenshtein(na, nb);
  const maxLen = Math.max(na.length, nb.length);
  if (1 - dist / maxLen >= 0.8) return true;

  // METHOD 2: token-based subset match
  // Every token in the shorter name must match some token in the longer name.
  // Match = exact OR one is a prefix of the other (both tokens ≥ 3 chars).
  // Catches:
  //   - Nicknames:      "Chris Earle" ↔ "Christopher Earle"
  //                     "Katie Smith" ↔ "Katherine Smith"
  //                     "Sam Jones"   ↔ "Samuel Jones"
  //   - Partial names:  "Ali"         ↔ "Ali Mohamedin"
  //                     "Nathan"      ↔ "Nathan Shields"
  // Does NOT match different people with same first name:
  //   "John Doe" vs "John Smith" — "doe" won't match "smith"
  const tokensA = toTokens(a);
  const tokensB = toTokens(b);
  if (tokensA.length === 0 || tokensB.length === 0) return false;

  const [shorter, longer] = tokensA.length <= tokensB.length
    ? [tokensA, tokensB]
    : [tokensB, tokensA];

  return shorter.every(t =>
    longer.some(l => {
      if (l === t) return true;
      if (t.length >= 3 && l.length >= 3 && (l.startsWith(t) || t.startsWith(l))) {
        return true;
      }
      return false;
    })
  );
}

// =====================
// Identify trainer + student speakers (no min threshold)
// =====================
const secsBySpeaker = new Map();
for (const c of cues) {
  const sp = (c.speaker || "").trim();
  if (!sp) continue;
  const durSec = (c.endMs - c.startMs) / 1000;
  if (durSec > 0) secsBySpeaker.set(sp, (secsBySpeaker.get(sp) || 0) + durSec);
}

const entries = [...secsBySpeaker.entries()].sort((a, b) => b[1] - a[1]);
const lecturerFromVtt = entries.length ? entries[0][0] : "";

const rawStudentSpeakers = entries
  .filter(([name]) => name !== lecturerFromVtt)
  .map(([name]) => name);

// =====================
// Attended students from Aggregate Attendees
// =====================
let attendanceRows = [];
try {
  attendanceRows = ($items("Aggregate Attendees")[0]?.json?.attendees) || [];
} catch (e) {
  attendanceRows = [];
}

const attendedStudents = attendanceRows
  .map(r => (r.Name || r.name || "").trim())
  .filter(Boolean)
  .filter(name => !lecturerFromVtt || !isSimilar(name, lecturerFromVtt));
const attendedCount = attendedStudents.length;

// Filter student speakers to those who actually attended (fuzzy)
const studentSpeakers = rawStudentSpeakers.filter(name =>
  attendedStudents.some(att => isSimilar(name, att))
);
const spokeCount = studentSpeakers.length;

// =====================
// Engagement calculation
// =====================
let engagementPercent = 0;
let engagement_score = 1;
let item7OverrideStatus = null;
let item7OverrideEvidence = null;
let item7OverrideReasoning = null;

if (attendedCount > 0) {
  engagementPercent = Number(((spokeCount / attendedCount) * 100).toFixed(2));

  if (engagementPercent >= 80) engagement_score = 5;
  else if (engagementPercent >= 60) engagement_score = 4;
  else if (engagementPercent >= 40) engagement_score = 3;
  else if (engagementPercent >= 20) engagement_score = 2;

  if (engagementPercent > 75) item7OverrideStatus = "Met";
  else if (engagementPercent >= 50) item7OverrideStatus = "Partially Met";
  else item7OverrideStatus = "Not Met";

  const silentStudents = attendedStudents.filter(att =>
    !rawStudentSpeakers.some(sp => isSimilar(att, sp))
  );

  item7OverrideEvidence =
    `Engagement score = ${spokeCount} / ${attendedCount} = ${engagementPercent}%.\n` +
    `Students who spoke (${studentSpeakers.length}): ${studentSpeakers.join(", ") || "(none)"}.\n` +
    `Students who attended but did not speak (${silentStudents.length}): ${silentStudents.join(", ") || "(none)"}.`;

  item7OverrideReasoning =
    `Engagement = matched speakers / attended. ${spokeCount} of ${attendedCount} attended students spoke. ` +
    `Threshold: Met > 75%, Partially Met 50–75%, Not Met < 50%. Result: ${engagementPercent}% → ${item7OverrideStatus}.`;
} else {
  engagementPercent = 0;
  engagement_score = 1;
}

// =====================
// Evidence formatter
// =====================
function formatClips(clips) {
  if (!Array.isArray(clips) || clips.length === 0) return "No evidence found";
  const out = [];
  clips.forEach((c, clipIdx) => {
    const start = c?.start || "";
    const end = c?.end || "";
    if (!start || !end) return;
    const blocks = blocksFromRange(start, end);
    if (!blocks.length) {
      out.push(`[${clipIdx + 1}] ${start} --> ${end}: No extractable quote for this range`);
      return;
    }
    const MAX_BLOCKS_PER_CLIP = 8, MAX_CHARS_PER_BLOCK = 260;
    blocks.slice(0, MAX_BLOCKS_PER_CLIP).forEach((b, i) => {
      const sp = (b.speaker || "").trim();
      const spTxt = sp ? ` (${sp})` : "";
      const quote = clipText(b.texts.join(" "), MAX_CHARS_PER_BLOCK);
      out.push(`[${clipIdx + 1}.${i + 1}] ${b.startStr} --> ${b.endStr}${spTxt}: ${quote || "No extractable quote"}`);
    });
  });
  return out.length ? out.join("\n") : "No evidence found";
}

function titledItemsToObject(arr, prefix) {
  const obj = {};
  if (!Array.isArray(arr)) return obj;
  arr.forEach((x, i) => {
    obj[`${prefix}_${i + 1}`] = {
      title: x?.title || "",
      evidence: formatClips(x?.evidence_clips || []),
      evidence_clips: x?.evidence_clips || []
    };
  });
  return obj;
}

function ksbsToObject(arr) {
  const obj = {};
  if (!Array.isArray(arr)) return obj;
  arr.forEach((k, i) => {
    obj[`ksb_${i + 1}`] = {
      type: k?.type || "",
      title: k?.title || "",
      evidence: formatClips(k?.evidence_clips || []),
      evidence_clips: k?.evidence_clips || []
    };
  });
  return obj;
}

// =====================
// AI fields
// =====================
const checklistRaw = data.checklist_evaluation;

const aiTrainer = data.session_info?.trainer || "";
const trainer = aiTrainer || lecturerFromVtt || (lectureRow.trainer ?? lectureRow.Trainer ?? "");

const date = baseSession.createdDateTime ? String(baseSession.createdDateTime).slice(0, 10) : "";

const strengthsObj = titledItemsToObject(data.overall_summary?.strengths || [], "strength");
const areasObj = titledItemsToObject(data.overall_summary?.areas_for_improvement || [], "area");
const aiOverallJudgement = data.overall_summary?.overall_judgement || "";
const ksbsObj = ksbsToObject(data.ksbs_covered || []);

const teachingQuality = data.teaching_quality || { rating_1_5: 3, comments: "", evidence_clips: [] };

// =====================
// Apply Item 7 override + fallback reasoning for items 1 & 2
// =====================
const startDiff = baseSession.startDifferenceMinutes;
const endDiff = baseSession.endDifferenceMinutes;

const checklist = checklistRaw.map((item, idx) => {
  if (idx === 6 && item7OverrideStatus !== null) {
    return { ...item, status: item7OverrideStatus, _item7_overridden: true };
  }

  if (idx === 0 && !String(item.reasoning || "").trim()) {
    const cmp = durationMinutes >= 105 ? ">=105" : "<105";
    return { ...item, reasoning: `METADATA.durationMinutes = ${durationMinutes} (${cmp}).` };
  }

  if (idx === 1 && !String(item.reasoning || "").trim()) {
    const sd = (startDiff === null || startDiff === undefined) ? "n/a" : startDiff;
    const ed = (endDiff === null || endDiff === undefined) ? "n/a" : endDiff;
    return { ...item, reasoning: `startDifferenceMinutes = ${sd}, endDifferenceMinutes = ${ed}. Status: ${item.status}.` };
  }

  return item;
});

const met_count = checklist.filter(i => i.status === "Met").length;
const partial_count = checklist.filter(i => i.status === "Partially Met").length;
const not_met_count = checklist.filter(i => i.status === "Not Met").length;

const engagedSpeakersObject = studentSpeakers.reduce((o, n, i) => {
  o[`speaker_${i + 1}`] = n;
  return o;
}, {});

// =====================
// FINAL OUTPUT
// =====================
return checklist.map((item, index) => {
  const checklist_order = index + 1;
  const session_id = baseSession.transcriptId;

  let severity = "pass";
  if (item.status === "Partially Met") severity = "warning";
  if (item.status === "Not Met") severity = "fail";

  let evidenceText, reasoningText;
  if (index === 6 && item._item7_overridden) {
    evidenceText = item7OverrideEvidence;
    reasoningText = item7OverrideReasoning;
  } else {
    evidenceText = formatClips(item.evidence_clips);
    reasoningText = item.reasoning || "";
  }

  return {
    json: {
      session_id,
      meeting_id: baseSession.meetingId,
      subject, trainer, date,
      checklist_order,
      session_id_match: `${session_id}_${checklist_order}`,
      checklist_item: item.item,
      status: item.status,
      reasoning: reasoningText,
      evidence: evidenceText,
      severity,
      duration: realDurationText,
      duration_minutes: durationMinutes,
      duration_score,
      Engagement: engagementPercent,
      engagement_percentage: engagementPercent,
      engagement_score,
      lecturer_name: lecturerFromVtt,
      attended_count: attendedCount,
      spoke_count: spokeCount,
      engaged_speakers_count: spokeCount,
      engaged_speakers: engagedSpeakersObject,
      ai_strengths: strengthsObj,
      ai_areas_for_development: areasObj,
      ai_overall_judgement: aiOverallJudgement,
      ksbs_covered: ksbsObj,
      teaching_quality_rating: teachingQuality.rating_1_5,
      teaching_quality_comments: teachingQuality.comments,
      teaching_quality_evidence: formatClips(teachingQuality.evidence_clips || []),
      met_count, partial_count, not_met_count,
      cancelled_session: false
    }
  };
});

// Collapse the 11 checklist rows into one lecture item for recording lookup.
// Every delivered lecture continues. is_perfect controls only qa_perfect_lectures.
const rows = items.map(item => item.json || {});
if (!rows.length) return [];

const first = rows[0];
const lecture = $items("Lecture Input")[0]?.json || {};
const uniqueOrders = new Set(
  rows.map(row => Number(row.checklist_order)).filter(Number.isFinite)
);
const allMet = rows.every(row => String(row.status || '').trim() === 'Met');
const metCount = Number(first.met_count ?? 0);
const meetingId = String(first.meeting_id || lecture.meetingId || '').trim();
const sessionId = String(first.session_id || '').trim();

if (!meetingId || !sessionId) {
  throw new Error('Cannot save recording metadata without meeting_id and session_id.');
}

const sessionDate = String(first.date || lecture.targetDate || '').slice(0, 10);
const subject = String(first.subject || lecture.subject || lecture.module || '').trim();
const isPerfect =
  metCount === 11 &&
  uniqueOrders.size === 11 &&
  allMet &&
  first.cancelled_session !== true;

return [{
  json: {
    lecture_key: `${sessionDate}|${subject}`,
    session_date: sessionDate,
    date: sessionDate,
    subject,
    module: lecture.module || null,
    trainer: first.trainer || null,
    engagement: first.Engagement ?? first.engagement ?? null,
    Engagement: first.Engagement ?? first.engagement ?? null,
    attended_count: first.attended_count ?? null,
    met_count: metCount,
    meeting_id: meetingId,
    session_id: sessionId,
    scheduled_start: lecture.scheduledStart || null,
    scheduled_end: lecture.scheduledEnd || null,
    is_perfect: isPerfect
  }
}];

function decodeSessionId(value) {
  const raw = String(value || '').trim();
  const base64 = raw.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
  try {
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

const guid = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';

return items.map((item, index) => {
  const lecture = item.json || {};
  const decoded = decodeSessionId(lecture.session_id);
  const transcript = decoded.match(
    new RegExp('(' + guid + ')-\\d+-TranscriptV2', 'i')
  );
  const allGuids = decoded.match(new RegExp(guid, 'ig')) || [];
  const callId = String(
    transcript?.[1] || allGuids.at(-1) || ''
  ).toLowerCase();

  return {
    json: {
      ...lecture,
      expected_call_id: callId || null,
      max_timestamp_difference_seconds: 15
    },
    pairedItem: { item: index }
  };
});

const lecture = $items('Extract Recording Call ID')[0]?.json || {};
const response = items[0]?.json || {};
const recordings = Array.isArray(response.value) ? response.value : [];
const expectedCallId = String(lecture.expected_call_id || '').toLowerCase();
const graphMatches = recordings.filter(recording =>
  String(recording?.callId || '').toLowerCase() === expectedCallId
);
const graphRecording = graphMatches.length === 1 ? graphMatches[0] : null;

let graphStatus = 'exact_graph_recording_found';
if (!expectedCallId) graphStatus = 'session_call_id_missing';
else if (graphMatches.length === 0) {
  graphStatus = 'graph_recording_not_found_for_call_id';
} else if (graphMatches.length > 1) {
  graphStatus = 'ambiguous_graph_recordings_for_call_id';
}

const compactDate = String(
  lecture.session_date || lecture.date || ''
).slice(0, 10).replace(/-/g, '');
const queryString = compactDate
  ? compactDate + ' "Meeting Recording" filetype:mp4'
  : '"Meeting Recording" filetype:mp4';

return [{
  json: {
    ...lecture,
    graph_recording_id: graphRecording?.id || null,
    graph_created_at: graphRecording?.createdDateTime || null,
    graph_content_correlation_id:
      graphRecording?.contentCorrelationId || null,
    graph_status: graphStatus,
    recording_search_date: compactDate,
    recording_search_query: queryString,
    recording_search_body: {
      requests: [{
        entityTypes: ['driveItem'],
        query: { queryString },
        from: 0,
        size: 500,
        fields: [
          'id',
          'name',
          'webUrl',
          'createdDateTime',
          'lastModifiedDateTime',
          'parentReference',
          'file'
        ]
      }]
    }
  }
}];

const teams = Array.isArray($json.value) ? $json.value : [];
if (!teams.length) {
  throw new Error(
    'No Teams returned. Credential needs Team.ReadBasic.All.'
  );
}

return teams.map((team, index) => ({
  json: {
    team_id: team.id,
    team_name: team.displayName || null
  },
  pairedItem: { item: index }
}));

const teams = $items('Expand Teams');
const output = [];

items.forEach((item, index) => {
  const team = teams[index]?.json || {};
  const channels = Array.isArray(item.json?.value) ? item.json.value : [];
  for (const channel of channels) {
    if (!channel?.id) continue;
    output.push({
      json: {
        ...team,
        channel_id: channel.id,
        channel_name: channel.displayName || null,
        channel_type: channel.membershipType || null
      }
    });
  }
});

if (!output.length) {
  throw new Error(
    'No Teams channels returned. Credential needs Channel.ReadBasic.All.'
